window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-df48098618d8d121"]={"versions": [{"id": "FIG-df48098618d8d121", "releases": ["R19-03", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Modellierung diagnostischer Service-Bedarfe (<code>ServiceNeeds</code>) speziell für die AUTOSAR Adaptive Platform im Rahmen der Metamodell-Spezifikation (<code>AUTOSAR_TPS_ManifestSpecification</code>). Das Diagramm illustriert die Spezialisierungshierarchie diagnostischer Fähigkeiten auf Software-Komponenten- bzw. Anwendungsebene zur Anforderung von Plattform-Diensten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Klassendiagramm umfasst folgende Klassen und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>ServiceNeeds</code>: Abstrakte Basisklasse, erbt von <code>Identifiable</code> (im Diagrammkopf kursiv vermerkt).\n</li><li><code>DiagnosticCapabilityElement</code>: Abstrakte Spezialisierung von <code>ServiceNeeds</code>. Definiert plattformspezifische Diagnose-Attribute:\n<ul class=\"fig-list\"><li><code>audience</code>: <code>DiagnosticAudienceEnum [0..*]</code> – Zielgruppe bzw. Adressatenkreis der Diagnosefunktionalität.\n</li><li><code>diagRequirement</code>: <code>DiagRequirementIdString [0..1]</code> – Referenzierung bzw. Bezeichner der zugrundeliegenden Diagnoseanforderung.\n</li><li><code>securityAccessLevel</code>: <code>PositiveInteger [0..1]</code> – Erforderliche Sicherheitsstufe (Security Access Level) für die Diagnoseausführung.\n</li></ul>\n</li><li>Spezialisierungen von <code>DiagnosticCapabilityElement</code>:\n<ul class=\"fig-list\"><li><code>DiagnosticIndicatorNeeds</code>: Modelliert Anforderungen an Anzeige- bzw. Warnindikatoren (z. B. MIL/Warnleuchten).\n</li><li><code>DiagnosticClearConditionNeeds</code>: Modelliert Bedingungen und Freigabekriterien für das Löschen von Diagnoseinformationen / Fehlerspeichereinträgen.\n</li><li><code>DiagnosticGenericUdsNeeds</code>: Modelliert generische UDS-Diagnosebedarfe zur flexiblen Abdeckung nicht standardisierter oder spezifischer Diagnose-Services.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe. Die Klassen definieren deklarative Entwurfselemente, die bei der Systemkonfiguration und Manifest-Generierung von Adaptive Applications ausgewertet werden, um die diagnostische Schnittstelle zum Diagnostic Management / Daemon (DM) der Adaptive Platform zur Laufzeit zu konfigurieren.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Konfigurationsrelevantes Metamodell für Adaptive Applications und Service-Manifeste. Die Spezialisierungen von <code>DiagnosticCapabilityElement</code> ermöglichen Software-Komponenten die standardisierte Deklaration ihrer Diagnoseanforderungen (<code>ServiceNeeds</code>). Die Attribute steuern Berechtigungen (Security-Level), Sichtbarkeiten (Audience) sowie Nachverfolgbarkeit zu Diagnose-Anforderungsspezifikationen.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-14a367317201f5f7", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Modellierung diagnostischer Service-Bedarfe (<code>ServiceNeeds</code>) speziell für die AUTOSAR Adaptive Platform im Rahmen der Metamodell-Spezifikation (<code>AUTOSAR_TPS_ManifestSpecification</code>). Das Diagramm illustriert die Spezialisierungshierarchie diagnostischer Fähigkeiten auf Software-Komponenten- bzw. Anwendungsebene zur Anforderung von Plattform-Diensten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Klassendiagramm umfasst folgende Klassen und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>ServiceNeeds</code>: Abstrakte Basisklasse, erbt von <code>Identifiable</code> (im Diagrammkopf kursiv vermerkt).\n</li><li><code>DiagnosticCapabilityElement</code>: Abstrakte Spezialisierung von <code>ServiceNeeds</code>. Definiert plattformspezifische Diagnose-Attribute:\n<ul class=\"fig-list\"><li><code>audience</code>: <code>DiagnosticAudienceEnum [0..*]</code> – Zielgruppe bzw. Adressatenkreis der Diagnosefunktionalität.\n</li><li><code>diagRequirement</code>: <code>DiagRequirementIdString [0..1]</code> – Referenzierung bzw. Bezeichner der zugrundeliegenden Diagnoseanforderung.\n</li><li><code>securityAccessLevel</code>: <code>PositiveInteger [0..1]</code> – Erforderliche Sicherheitsstufe (Security Access Level) für die Diagnoseausführung.\n</li></ul>\n</li><li>Spezialisierungen von <code>DiagnosticCapabilityElement</code>:\n<ul class=\"fig-list\"><li><code>DiagnosticIndicatorNeeds</code>: Modelliert Anforderungen an Anzeige- bzw. Warnindikatoren (z. B. MIL/Warnleuchten).\n</li><li><code>DiagnosticClearConditionNeeds</code>: Modelliert Bedingungen und Freigabekriterien für das Löschen von Diagnoseinformationen / Fehlerspeichereinträgen.\n</li><li><code>DiagnosticGenericUdsNeeds</code>: Modelliert generische UDS-Diagnosebedarfe zur flexiblen Abdeckung nicht standardisierter oder spezifischer Diagnose-Services.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe. Die Klassen definieren deklarative Entwurfselemente, die bei der Systemkonfiguration und Manifest-Generierung von Adaptive Applications ausgewertet werden, um die diagnostische Schnittstelle zum Diagnostic Management / Daemon (DM) der Adaptive Platform zur Laufzeit zu konfigurieren.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Konfigurationsrelevantes Metamodell für Adaptive Applications und Service-Manifeste. Die Spezialisierungen von <code>DiagnosticCapabilityElement</code> ermöglichen Software-Komponenten die standardisierte Deklaration ihrer Diagnoseanforderungen (<code>ServiceNeeds</code>). Die Attribute steuern Berechtigungen (Security-Level), Sichtbarkeiten (Audience) sowie Nachverfolgbarkeit zu Diagnose-Anforderungsspezifikationen.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-df48098618d8d121", "to": "FIG-14a367317201f5f7", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
